    if (action.type === "farm_conversion") add(action.playerId, Number(action.prestigeAward) || 0, "civic_farm");
    if (action.type === "sector_development") add(action.playerId, Number(action.prestige) || 0, "sector_development");
    if (action.type === "fortification_construction") add(action.playerId, Number(action.prestigeAward) || 0, "fortification_construction");
    if (action.type === "reforestation") add(action.playerId, Number(action.prestigeAward) || 0, "reforestation");
